<script setup>
import {shallowRef,onMounted,onUnmounted} from 'vue'
import {features,news,members,asset,path,fmt} from '../data'
import Icon from '../components/Icon.vue'
import Markets from '../components/Markets.vue'
import MarketTicker from '../components/MarketTicker.vue'
import PartnerMarquee from '../components/PartnerMarquee.vue'
import {useDemoQuotes} from '../composables/useDemoQuotes'
const {quotes,stocks,paused:quotesPaused,toggle:toggleQuotes}=useDemoQuotes()
import {session} from '../session'
function pause(){clearInterval(timer)}
const member=shallowRef(0)
let timer
onMounted(()=>{if(!matchMedia('(prefers-reduced-motion: reduce)').matches)timer=setInterval(()=>member.value=(member.value+1)%members.length,7000)})
onUnmounted(()=>clearInterval(timer))
function cycle(n){clearInterval(timer);member.value=(member.value+n+members.length)%members.length}
</script>
<template><div class="home">
<MarketTicker :rows="quotes" :paused="quotesPaused"/>
<section class="accent-glow relative overflow-hidden"><div class="grid-bg absolute inset-0"></div><div class="relative z-10 mx-auto site-container px-6 py-16 md:py-24 lg:py-32"><div class="grid items-center gap-12 lg:grid-cols-12"><div class="lg:col-span-7"><div class="mb-8 flex items-center gap-3"><span class="tag tag-accent"><span class="pulse-dot !h-1.5 !w-1.5"></span>{{ $t("home.hero.badge") }}</span></div><h1 class="font-display text-fg mb-6 text-4xl leading-[1] tracking-tight md:text-6xl lg:text-7xl">{{ $t("home.hero.title") }}</h1><p class="text-fg-secondary mb-10 max-w-xl text-lg leading-relaxed">{{ $t("home.hero.desc") }}</p><div class="flex flex-wrap items-center gap-6"><RouterLink :to="path(session.loggedIn?'/trade/futures/BTCUSD':'/register')" class="btn-primary">{{ $t("auth.registerComplete.actionTrade.title") }}<Icon name="arrow-right"/></RouterLink><RouterLink :to="path('/ai-quant/quant-fund')" class="green-link">{{ $t("home.hero.exploreQuantFund") }}<Icon name="arrow-right" green/></RouterLink></div></div><div class="lg:col-span-5"><div class="hero-app-stage"><img class="hero-app-rings" src="/NewQuantCapital/assets/bfe16884100d8202.svg" :alt="$t(&quot;&quot;)"/><div class="hero-app-aura" aria-hidden="true"></div><img class="hero-app-mockup" src="/NewQuantCapital/assets/newquantcapital-app-mockup.webp" :alt="$t('home.hero.appMockupAlt',{brand:'NewQuantCapital'})" width="500" height="985" fetchpriority="high"/><div class="hero-app-reflection" aria-hidden="true"></div><span class="hero-app-pip">{{ $t("home.hero.appMockupPip") }}</span></div></div></div></div></section>
<Markets :rows="quotes" :stocks="stocks" :paused="quotesPaused" @toggle="toggleQuotes"/>
<section class="section-bordered section-pad"><div class="container"><h2 class="section-heading">{{ $t("home.ui.whyNewquantcapital") }}</h2><p class="section-desc">{{ $t("home.ui.fourReasonsTradersMoveToNewquantcapitalAndStayBuilt") }}</p><div class="features-grid"><article v-for="f in features" :key="f[0]" class="feature-card"><img decoding="async" :src="asset(f[2])" :alt="$t(f[0])" loading="lazy"/><div><Icon :name="f[3]" green/><h3>{{ $t(f[0]) }}</h3><p>{{ $t(f[1]) }}</p><RouterLink :to="path(f[4])" class="green-link">{{ $t("charity.campaigns.view") }}<Icon name="chevron-right" green/></RouterLink></div></article></div></div></section>
<section class="section-pad withdrawals"><div class="container"><h2 class="section-heading">{{ $t("home.payments.title") }}</h2><p class="section-desc">{{ $t("home.payments.subtitle") }}</p><div class="payment-logos"><img decoding="async" v-for="payment in ['visa','mastercard','swift','sepa','usdt','usdc','btc','eth']" :key="payment" :src="'/NewQuantCapital/assets/payment-'+payment+'.svg'" :alt="$t(payment.toUpperCase())" loading="lazy"/></div></div></section>
<section class="section-pad section-bordered"><div class="container"><div class="section-row"><h2 class="section-heading">{{ $t("home.news.title") }}<em>{{ $t("home.news.titleHighlight") }}</em></h2><RouterLink :to="path('/news')">{{ $t("home.news.viewAll") }}</RouterLink></div><div class="insights-grid"><RouterLink :to="path('/news/'+news[0].id)" class="insight-feature"><img decoding="async" :src="asset(news[0].image)" :alt="$t(news[0].title)" loading="lazy"/><small>{{ $t("CoinTeleGraph · ") }}{{ $t(news[0].hours) }}{{ $t("home.ui.hoursAgo") }}</small><h3>{{ $t(news[0].title) }}</h3><p>{{ $t(news[0].summary) }}</p></RouterLink><div class="insight-stack"><RouterLink v-for="n in news.slice(1)" :key="n.id" :to="path('/news/'+n.id)"><small>{{ $t("CoinTeleGraph · ") }}{{ $t(n.hours) }}{{ $t("home.ui.hoursAgo") }}</small><h3>{{ $t(n.title) }}</h3><p>{{ $t(n.summary) }}</p></RouterLink></div></div></div></section>
<section class="section-pad section-bordered members"><div class="container"><h2 class="section-heading">{{ $t("home.founding.title") }}</h2><div class="member-slider" @mouseenter="pause"><button :aria-label="$t(&quot;home.founding.prev&quot;)" class="icon-button" @click="cycle(-1)"><Icon name="chevron-left"/></button><div><img decoding="async" loading="lazy" :src="asset(members[member][1])" :alt="$t(members[member][0])"/><h3>{{ $t(members[member][0]) }}</h3><p>{{ $t("home.partners.title") }}</p></div><button :aria-label="$t(&quot;home.founding.next&quot;)" class="icon-button" @click="cycle(1)"><Icon name="chevron-right"/></button></div><p class="member-copy">{{ $t('home.founding.description',{brandName:'NewQuantCapital',names:members.map(m=>$t(m[0])).join(', ')}) }}</p></div></section>
<section class="section-pad section-bordered partners"><h2 class="section-heading">{{ $t("home.partners.title") }}</h2><PartnerMarquee/></section>
<section class="home-cta section-bordered"><div class="grid-bg absolute inset-0"></div><div class="container"><h2 class="section-heading">{{ $t("home.cta.title") }}</h2><p>{{ $t("home.cta.desc") }}</p><RouterLink :to="path(session.loggedIn?'/trade/futures/BTCUSD':'/register')" class="btn-primary">{{ $t(session.loggedIn?"home.cta.tradeNow":"home.cta.start") }}<Icon name="arrow-right"/></RouterLink><small>{{ $t("home.cta.guaranteeLine") }}</small></div></section>
</div></template>
